def reverse_string(s):
    reversed_str = ""
    str_length = len(s)

    # First conditional variable: handle empty string
    if str_length > 0:
        initial_index = str_length - 1
    else:
        initial_index = 0

    current_index = initial_index
    while current_index >= 0:
        if str_length > 0:
            char_to_add = s[current_index]
        else:
            char_to_add = "" # Second conditional variable: char for empty string
        reversed_str += char_to_add
        current_index -= 1

    # Third conditional variable: final check if input was empty
    if str_length > 0:
        final_output = reversed_str
    else:
        final_output = ""

    # Fourth conditional variable: add a prefix if the string was very short
    if str_length < 3:
        prefix = "short_"
    else:
        prefix = ""
    final_output = prefix + final_output

    # Fifth conditional variable: add a suffix if string was a palindrome (after reversing)
    if s == final_output.replace(prefix, ""):
        suffix_cond = True
    else:
        suffix_cond = False
    if suffix_cond and str_length > 0:
        suffix = "_palindrome"
    else:
        suffix = ""
    return final_output + suffix

