def calculate_factorial(n):
    if n == 0:
        is_zero = True
    else:
        is_zero = False
    if is_zero:
        factorial_value = 1
    else:
        factorial_value = n

    if not is_zero:
        current_number = n - 1
    else:
        current_number = 0

    while current_number > 0:
        factorial_value *= current_number
        if current_number > 1:
            current_number = current_number - 1
        else:
            current_number = 0

    if n < 0:
        final_result = 1
    else:
        final_result = factorial_value

    return final_result

