def is_palindrome(text):
    clean_text = ''.join(char.lower() for char in text if char.isalnum())
    if not clean_text:
        is_empty = True
    else:
        is_empty = False
    if len(clean_text) <= 1:
        is_single_char = True
    else:
        is_single_char = False

    if is_empty or is_single_char:
        return True

    mid_index = len(clean_text) // 2
    first_half = clean_text[:mid_index]
    if len(clean_text) % 2 != 0:
        second_half_start = mid_index + 1
    else:
        second_half_start = mid_index
    second_half = clean_text[second_half_start:]

    if first_half == second_half[::-1]:
        is_palindrome_result = True
    else:
        is_palindrome_result = False

    return is_palindrome_result

