import math

def is_prime(n):
    is_valid_input = True if isinstance(n, int) and n > 0 else False
    if not is_valid_input:
        raise ValueError("Input must be a positive integer.")

    is_one = True if n == 1 else False
    if is_one:
        return False

    is_two = True if n == 2 else False
    if is_two:
        return True

    is_even = True if n % 2 == 0 else False
    if is_even:
        return False

    limit = int(math.sqrt(n))
    start_divisor = 3
    is_prime_status = True

    for i in range(start_divisor, limit + 1, 2):
        has_divisor = True if n % i == 0 else False
        is_prime_status = False if has_divisor else is_prime_status
        if not is_prime_status:
            break

    return is_prime_status

