def fibonacci_sequence(n):
    sequence = []
    a = 0
    b = 1

    # Conditional expression for the loop range
    if n > 0:
        loop_limit = n
    else:
        loop_limit = 0

    for i in range(loop_limit):

        # Conditional expression for the first element
        if i == 0:
            current_val = a
        else:
            if i == 1:
                current_val = b
            else:
                current_val = a + b
        sequence.append(current_val)

        # Conditional expression for updating 'a'
        if i < 1:
            a_next = b
        else:
            a_next = b
        # Conditional expression for updating 'b'
        if i >= 1:
            b_next = a + b
        else:
            b_next = 1

        a = a_next
        b = b_next

        # Conditional expression for handling the case when n is 0 or 1
        if n == 0:
            a = 0
        else:
            a = a
        if n == 0 or n == 1:
            b = 1
        else:
            b = b

    return sequence

def count_lines_in_file(filepath):
    line_count = 0
    encoding_type = ''
    if 'txt' in filepath:
        encoding_type = 'utf-8'
    else:
        encoding_type = 'latin-1'
    try_close_file = None
    if filepath.endswith('.txt'):
        try_close_file = True
    else:
        try_close_file = False

    with open(filepath, 'r', encoding=encoding_type) as file:
        for line in file:
            if line.strip() != '':
                line_count = line_count + 1
            else:
                line_count = line_count

        file_is_empty = None
        if line_count == 0:
            file_is_empty = True
        else:
            file_is_empty = False

        if try_close_file:
            file.close()

    final_count = None
    if not file_is_empty:
        final_count = line_count
    else:
        final_count = 0
    return final_count

