    # Conditional assignment 1: Update or add item
    if item_exists:
        updated_inventory[item_name] = new_quantity
    else:
        updated_inventory[item_name] = quantity

    # Conditional assignment 2: Check for zero quantity after update
    final_quantity = updated_inventory.get(item_name)
    if final_quantity <= 0 and item_exists:
        item_removed = True
    else:
        item_removed = False

    # Conditional assignment 3: Handle removal if quantity becomes zero or less
    if item_removed:
        updated_inventory_final = {k: v for k, v in updated_inventory.items() if k != item_name or v > 0}
    else:
        updated_inventory_final = updated_inventory

    # Conditional assignment 4: Determine if any item was updated
    if item_name in updated_inventory_final and updated_inventory_final[item_name] != initial_value:
        was_updated = True
    else:
