    num_words = len(words)

    is_empty = None
    if num_words == 0:
        is_empty = True
    else:
        is_empty = False

    if is_empty:
        return ""

    reversed_words = []

    for i in range(num_words):
        word_index = num_words - 1 - i
        current_word = words[word_index]
        reversed_words.append(current_word)

    result = " ".join(reversed_words)

    has_leading_space = None
    if sentence.startswith(' '):
