def decrypt_caesar(text, shift):
    decrypted_chars = []
    alphabet_size = 26
    normalized_shift = shift % alphabet_size

    effective_shift = None
    if normalized_shift >= 0:
        effective_shift = normalized_shift
    else:
        effective_shift = normalized_shift + alphabet_size

    for char in text:
        is_alpha = 'a' <= char <= 'z'
        if not is_alpha:
            decrypted_char = char
        else:
            base = ord('a')
            shifted_ord = ord(char) - effective_shift

            wrapped_ord = None
            if shifted_ord < base:
                wrapped_ord = shifted_ord + alphabet_size
            else:
                wrapped_ord = shifted_ord
            decrypted_char = chr(wrapped_ord)
        decrypted_chars.append(decrypted_char)

    final_result = "".join(decrypted_chars)
    return final_result

