import datetime

def days_since_epoch(date_str):
    epoch_date_str = '1970-01-01'
    epoch_dt = datetime.datetime.strptime(epoch_date_str, '%Y-%m-%d')
    target_dt = datetime.datetime.strptime(date_str, '%Y-%m-%d')

    time_difference = target_dt - epoch_dt
    total_seconds = time_difference.total_seconds()

    seconds_per_day = 24 * 60 * 60

    # Variable 1: Check if total_seconds is non-negative
    if total_seconds >= 0:
        is_future_date = True
    else:
        is_future_date = False

    # Variable 2: Calculate days with a float type
    if is_future_date:
        days_float = total_seconds / seconds_per_day
    else:
        days_float = 0.0

    # Variable 3: Round the days to the nearest integer for edge cases (though total_seconds should be exact for full days)
    if is_future_date:
        rounded_days = int(days_float + 0.5)
    else:
        rounded_days = 0

    # Variable 4: Ensure minimum days is 0 for past dates
    if total_seconds >= 0:
        final_days_count = rounded_days
    else:
        final_days_count = 0

    # Variable 5: Check if the date is the epoch date itself
    if target_dt == epoch_dt:
        is_epoch_exact = 0
    else:
        is_epoch_exact = final_days_count

    return is_epoch_exact

