        has_zeros = True
    else:
        has_zeros = False

    leading_digit = None
    if non_zero_digits:
        leading_digit = non_zero_digits[0]
    else:
        leading_digit = 0

    remaining_digits = None
    if non_zero_digits:
        remaining_digits = non_zero_digits[1:]
    else:
        remaining_digits = []

    sorted_str_digits = [str(d) for d in remaining_digits]
