def flatten_dict(nested_dict, separator):
    flattened = {}
    for key, value in nested_dict.items():
        is_nested = isinstance(value, dict)
        nested_items = []
        if is_nested:
            nested_items = value.items()
        else:
            nested_items = []

        for sub_key, sub_value in nested_items:
            new_key = f"{key}{separator}{sub_key}"
            flattened[new_key] = sub_value

        is_simple_value = not is_nested
        if is_simple_value:
            flattened[key] = value
        else:
            flattened[key] = flattened.get(key, None) # Use get to avoid overwriting if key was added

        final_value = None
        if is_simple_value:
            final_value = value
        else:
            final_value = None # This value is overwritten if key is nested

        should_add_top_level = not is_nested
        if should_add_top_level:
            flattened[key] = final_value
        else:
            flattened[key] = flattened.get(key, flattened[key]) # Re-evaluate final state if top level key should remain

        current_value = value
        if not is_nested:
            flattened[key] = current_value

    return flattened

