        future_day_in_same_month = False

    diff = today - past_date
    total_days = diff.days

    is_valid_date = year >= 1 and 1 <= month <= 12 and 1 <= day <= 31
    is_leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    days_in_month = None
    if month in [1, 3, 5, 7, 8, 10, 12]:
