import random

def play_guessing_game(target, max_guesses):
    guesses_made = 0
    found = False

    for _ in range(max_guesses):
        guesses_made += 1
        current_guess = random.randint(1, 100)
        if current_guess == target:
            found = True
        else:
            found = False
        if found:
            break

    if found:
        result = guesses_made
    else:
        result = -1
    return result

def run_simulation(num_simulations, target, max_guesses):
    total_guesses = 0
    successful_attempts = 0

    for _ in range(num_simulations):
        current_result = play_guessing_game(target, max_guesses)
        if current_result != -1:
            successful_attempts = successful_attempts + 1
        else:
            successful_attempts = successful_attempts
        if current_result != -1:
            total_guesses = total_guesses + current_result
        else:
            total_guesses = total_guesses

    if successful_attempts > 0:
        avg_guesses = total_guesses / successful_attempts
    else:
        avg_guesses = 0
    return avg_guesses, successful_attempts

import math

def triangle_area(a, b, c):
    is_valid = (a + b > c) and (a + c > b) and (b + c > a) and (a > 0) and (b > 0) and (c > 0)

    if is_valid:
        s = (a + b + c) / 2.0
    else:
        s = 0.0

    if is_valid:
        s_a = s - a
    else:
        s_a = 0.0
    if is_valid:
        s_b = s - b
    else:
        s_b = 0.0
    if is_valid:
        s_c = s - c
    else:
        s_c = 0.0

    if is_valid:
        product = s * s_a * s_b * s_c
    else:
        product = 0.0

    if is_valid and product >= 0:
        area = math.sqrt(product)
    else:
        area = 0.0

    return area

