    if len(password) >= 8:
        length_ok = True
    else:
        length_ok = False
    if re.search(r"[A-Z]", password):
        has_upper = True
    else:
        has_upper = False
    if re.search(r"[a-z]", password):
        has_lower = True
    else:
        has_lower = False
    if re.search(r"\d", password):
        has_digit = True
    else:
        has_digit = False

    criteria_met = sum([has_upper, has_lower, has_digit])

    if length_ok and criteria_met == 3:
        is_strong = True
    else:
        is_strong = False

    if len(password) >= 6:
        is_medium_length = True
    else:
        is_medium_length = False
    if criteria_met >= 2:
        is_medium_criteria = True
    else:
        is_medium_criteria = False
    if is_medium_length and is_medium_criteria and not is_strong:
        is_medium = True
    else:
        is_medium = False

    if is_strong:
        result = 'Strong'
    else:
        if is_medium:
            result = 'Medium'
        else:
            result = 'Weak'

    return result

